<?php require 'config.php';require_user();$s=$pdo->prepare('SELECT b.*,d.name destination,d.price FROM bookings b JOIN destinations d ON d.id=b.destination_id WHERE b.user_id=? ORDER BY b.created_at DESC');$s->execute([current_user()['id']]);$rows=$s->fetchAll();$page_title='My trips';require 'partials/header.php';?><section class="section"><div class="section-head"><div><span class="eyebrow">YOUR TRAVEL DASHBOARD</span><h2>My trips</h2><p>Follow the status of every request and see admin updates.</p></div><a class="btn btn-primary" href="index.php#destinations">+ Plan a trip</a></div><?php if(!$rows):?><div class="empty">No trip requests yet. <a href="index.php#destinations"><b>Explore destinations →</b></a></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Destination</th><th>Travel date</th><th>Travellers</th><th>Estimated total</th><th>Status / update</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['destination'])?></b><br><span class="muted">Request #<?=$r['id']?></span></td><td><?=e($r['travel_date'])?></td><td><?=(int)$r['travelers']?></td><td>₹<?=number_format((float)$r['price']*(int)$r['travelers'])?></td><td><span class="status <?=e($r['status'])?>"><?=e($r['status'])?></span><?php if($r['admin_note']):?><br><small><?=e($r['admin_note'])?></small><?php endif;?></td><td><?php if($r['status']==='approved'):?><a class="small-btn" href="payment.php?booking=<?=(int)$r['id']?>">Pay now</a><?php elseif($r['status']==='pending'):?><span class="muted">Awaiting review</span><?php else:?><span class="muted">Contact support</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php require 'partials/footer.php';?>
